/*
 * mtp-stdcpp -- the StateOS stdc++ package adapted to µOS++ III, tested with
 * µTest++. GENERATED by micro-os-scaffold (--stdcpp).
 *
 * The libstdc++ parts a bare-metal target does not get from the toolchain
 * (the gthread layer, std::thread, future/promise/async, the chrono clocks,
 * emulated TLS, and C++20 barrier/latch/semaphore), from the workspace's
 * third_party/stateos-stdc++. On a board whose other cores the support can
 * start, they all join the scheduler first; otherwise the same checks run on
 * one core.
 *
 *   01 - std::thread and TLS   create/join/detach, jthread, ids, sleep, thread_local
 *   02 - promise and future    value, void, wait_for status, shared_future
 *   03 - packaged_task, async  deferred vs async, set_value_at_thread_exit
 *   04 - mutexes and call_once lock_guard, timed, recursive, once
 *   05 - sync primitives       condition_variable, semaphores, latch, barrier
 *   06 - chrono                the two clocks, sleeps, duration conversions
 *
 * The suites are the ones verified on the Raspberry Pi 4 B (4 cores), the
 * Pico 2 (2 cores, and single-core under QEMU) and the WeAct F411CE (1 core).
 * Each lives in its own suite-*.cpp file and registers itself.
 */
#include <mtp_board.hpp>

#include <cstdio>

int
os_main (int argc, char* argv[])
{
  mtp_board::start ("mtp-stdcpp");
#if defined(MTP_HAS_SMP_BOOT) && MTP_HAS_SMP_BOOT
  // The other cores join the scheduler; on a single-core image the board
  // support reports one core and returns.
  mtp_board::release_cores ();
#endif
  std::printf ("# stdc++: StateOS stdc++ adapted to µOS++ III, %u core%s\n",
               static_cast<unsigned> (OS_NCPU),
               static_cast<unsigned> (OS_NCPU) == 1 ? "" : "s");
  return mtp_board::run (argc, argv);
}

#include <mtp_startup.hpp>
